contains
 integer function var_index(name) result(idx)
  character(len=*), intent(in) :: name
  integer :: i
  idx=0
  do i=1,N_VARS
   if (VAR_NAME(i) /= name) cycle
   idx=i
   return
  end do
 end function
 integer function dim_index(name) result(idx)
  character(len=*), intent(in) :: name
  integer :: i
  idx=0
  do i=1,N_DIMS
   if (DIM_NAME(i) /= name) cycle
   idx=i
   return
  end do
 end function
end module
